// Handy listens to global shortcuts locally
fn handle_shortcut_event(event: ShortcutEvent) {
    if event == ShortcutEvent::Pressed {
        audio_stream::start_recording();
    } else {
        let text = whisper::transcribe(audio_stream::stop_recording());
        clipboard::paste_into_active_window(text);
    }
}

